import{_ as s,H as i,f as B,i as t}from"./chunks/framework.BH2BK_3i.js";const F=JSON.parse('{"title":"期中测试答案-这些问题，你都答对了吗？","description":"","frontmatter":{},"headers":[],"relativePath":"中间件核心技术与实战/期中测试答案-这些问题，你都答对了吗？.md","filePath":"中间件核心技术与实战/期中测试答案-这些问题，你都答对了吗？.md","lastUpdated":1795537466000}'),e={name:"中间件核心技术与实战/期中测试答案-这些问题，你都答对了吗？.md"};function a(A,E,n,p,l,h){return i(),B("div",null,[...E[0]||(E[0]=[t(`<h1 id="期中测试答案-这些问题-你都答对了吗" tabindex="-1">期中测试答案-这些问题，你都答对了吗？ <a class="header-anchor" href="#期中测试答案-这些问题-你都答对了吗" aria-label="Permalink to &quot;期中测试答案-这些问题，你都答对了吗？&quot;">​</a></h1><p>你好，我是丁威。</p><p>这节课我们来回答一下上节课的问题，希望通过梳理这些问题，可以进一步加深你对知识的理解。</p><ol><li>MyCat 数据库中间件与 ShardingJDBC 在架构思想上有什么差异？</li></ol><p>MyCat 数据库中间件的设计理念是代理模式，这是一种高度中心化的设计，所有的路由配置都会存储在 MyCat 数据库中间件中。具体的工作机制是，所有客户端将所有请求发送到MyCat，然后 MyCat 根据配置的路由规则将请求发送到真实的后端数据库。</p><p>这种架构模式在数据量较少的情况下确实能提升性能，但如果请求数继续增加，就有可能出现问题，你可以先看看下面这张图片：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/1.png" alt=""></a></p><p>如果数据库需要存储的数据逐步增加，我们就要对后端数据库进行扩容，这个无可厚非。但如此一来，存储的数据会越来越多，基于代理模式，所有的请求都必须经过 MyCat 这个中心节点。一旦这个节点出现故障，将导致系统不可用。</p><p>而 ShardingJDBC 采取了去中心化的设计，系统架构如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/2.png" alt=""></a></p><p>从这张图可以看到，ShardingJDBC 是将所有的路由信息嵌入到应用进程中，在客户端进行路由计算，然后连接后端真实的数据库。如果要对后端数据库进行扩容，只需要更新一下路由注册信息就可以了，不会带来额外的资源损耗，也不存在单点故障。</p><ol start="2"><li>在订单中心有创建订单、查询订单两个微服务。其中，查询订单必须同时支持“按商家”和“按用户”两个维度。为了应对双十一这种大促场景，在数据存储和数据读写方面你会如何进行架构设计？</li></ol><p>通常为了应对流量高峰，我们会首先在入口流量引用 MQ，然后在数据库存储领域引入分库分表。同时，为了避免查询请求对写入性能的影响，会引入读写分离机制。但是我们不能简单地在数据库层面使用读写分离，因为分库分表后，使用 Join 等复杂语句通常会遇到性能瓶颈，所以应该将数据库数据实时同步到 Elasticsearch 中，最后的架构设计大概如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/3.png" alt=""></a></p><ol start="3"><li>红黑树的左右旋转、染色其实是不需要死记硬背的。下面这棵二叉树，你会怎样操作让它符合红黑树的定义呢？</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/4.png" alt=""></a></p><p>红黑树的染色和左右旋转是有窍门的。</p><p>我们先看染色，需要变换染色的情况，通常是相关的三个节点组成的结构是一个父节点带两个节点，我们需要将其中一个黑色的叶子结点的颜色传递到父节点。</p><p>然后再来谈左旋和右旋。其实它们的原理就是通过降低树的高度来实现平衡，但调整后需要确保根节点比左节点大，比右节点小。左旋或者右旋的触发场景为：连续两个红颜色节点。</p><p>我们说回到这道题。0037 的左节点为 0035，0035 的左节点为 0025，那这三个节点，从0025 视角来看，有 3“层”，我们要把它们变成两层。一个简单的方法就是我们从这 3 个节点中找到中间值节点，这里是 0035 节点，然后把比中间节点小的节点 (0025) 放入到 0035 的左节点，把比中间件节点大的节点（0037）放入到中间值节点（0035）的右子树即可。</p><p>经过旋转后，我们可以得到下面这张图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/5.png" alt=""></a></p><p>但这个时候还是有两个连续的红色节点，这样会导致每条链路的黑色节点数量不一致。又因为0025，0037 这两个节点已经在同一层次了，这个时候我们可以调整节点的颜色让它符合红黑树的定义，我们只需要将 0037 的颜色传递给它的父节点就可以了，最终为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/6.png" alt=""></a></p><ol start="4"><li>JUC 定时调度线程池底层的实现原理是什么？如果要管理上万个定时任务，需要怎么处理呢？</li></ol><p>JUC 的线程调度底层的队列存储结构是 PriorityQueue，又叫做最小堆，它的具体的实现原理如下。</p><ul><li><p>在将调度任务提交到线程池之前，首先计算出下一次需要执行的时间戳，通过时间戳来计算优先级，将其存入最小堆中，这样就确保了最先需要执行的调度任务位于最小堆的顶部 (也就是根节点)。</p></li><li><p>然后开一个定时任务，拿队列中第一个元素和当前时间进行比较：</p></li><li><p>如果下一次执行时间大于等于当前时间，则将队列中第一个元素（调度任务）从队列中移除，投入线程池中执行。</p></li><li><p>如果下一次执行时间小于当前时间，则不处理，因为队列中最小的待执行任务都还没有到执行时间，其他任务一定也是这样。</p></li></ul><p>但是如果需要调度的任务很多（例如上万个），这些任务的触发时间只相隔个几秒，这种通过一个线程一个一个检测任务的方式，很容易导致任务调度执行不精确。</p><p>为了解决这个问题，业界引入了时间轮算法，它的意思是引入时间轮，每一个轮代表一个时间刻度，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/7.png" alt=""></a></p><p>例如，图中每一个刻度代表 1s。因为有 8 个格子，就代表 8 秒，也就是说，这个时间轮可以管理延迟调度时间在 8s 内的任务。如果想要增加延迟调度的时间范围，只要增加格子的数量即可。</p><p>具体怎么操作呢？</p><ul><li><p>首先计算要调度的任务的延迟时间，将它换算成相应的刻度放到指定的格子里，每一个格子都会维护一个任务列表。</p></li><li><p>然后使用一个线程（类似于钟表中的秒针）以固定频率（单个格子代表的时间长度）驱动指针，指针指向的格子内所有的任务到期后，一次性出发所有的定时任务，执行精度并不会随着要触发的任务数量增加而发生变化。</p></li></ul><ol start="5"><li>如何复用线程？如何优雅地停止一个线程？</li></ol><p>一个线程走向消亡的触发条件是线程的 run 方法的结束，因此，要复用一个线程的方法是不让run 方法结束。我们通常采用的方法是：“while(true) + 从阻塞队列中获取任务”。因为如果阻塞任务中没有任务可执行，线程会阻塞，不会浪费 CPU 资源；而一旦阻塞队列中有新的任务加入，就能立马唤醒线程执行对应的任务了。</p><p>要停止一个线程，我们不能直接调用线程的 stop 方法，而是需要在 run 方法加入中断检测机制。在 run 方法中如果检测线程中断位被设置，则跳出循环，结束 run 方法的运行，从而达到停止线程的目的。</p><ol start="6"><li>多线程编程中，线程与线程之间有两种主要的关系：互斥与协作。你能结合自己的实际工作场景分别举例说明吗？</li></ol><p>互斥，通常是在多个线程要访问同一个公共资源，而这个公共资源又不允许多个线程同时访问时出现。这个时候需要引入锁来保护共享资源，达到多线程串行访问的效果。这在实际生产中非常常见，例如，多个线程要更新数据库中的同一行数据时，就涉及到锁的使用。</p><p>协作其实看出是对一个任务进行步骤拆解，然后让这些步骤可以并行执行，以此提升性能。</p><p>例如，MQ 的消息拉取线程与队列负载均衡这两个线程就是典型的协作模式。这两个线程共同完成 MQ 消息的拉取，它们使用一个公共的阻塞队列相互协作。负载均衡算法负责计算队列的负载情况，向阻塞队列中生产任务；而消息拉取线程负责从阻塞队列中获取任务，并执行具体的消息拉取动作。如果阻塞队列中没有任务，那么消息拉取线程就要阻塞，在生产出新的拉取任务后，负载均衡线程会再通知消息拉取线程。这两者之间是相互协作，相互制约的关系。</p><ol start="7"><li>锁的底层数据结构是什么？</li></ol><p>它包括锁的持有者线程、锁的重入次数、阻塞队列和条件等待队列。</p><p>锁的持有者线程拥有对被保护资源的操作权，而且在整个过程中，支持对锁进行多次锁定。</p><p>同步阻塞队列存放的都是竞争锁失败的线程，主要表征的是线程之间的竞争和互斥。</p><p>条件等待队列中存储的是因为某一个条件不满足而需要阻塞的线程，通常需要被其他线程主动唤醒，主要表征的是线程的协作。</p><ol start="8"><li>为什么 Object.wait 方法会释放占用的锁？如果锁没有被释放，会产生什么影响？</li></ol><p>我们用前面讲的面包工程的例子加以说明。例如下面一段代码是面包生产者向仓库中生产面包的代码实现：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Bread bread) throws InterruptedException {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    synchronized</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (breads) {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//锁定资源</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (breads.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.maxCapacity) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             // 没有可存储的空间，阻塞生产者，等待有存储空间后再继续</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             breads.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">             log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         breads.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bread);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">         breads.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">notifyAll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>生产者线程调用 put 方法后，是因为仓库（具体是 List breads）中没有容量，所以被阻塞。但如果不释放锁，就没有线程能从 breads 中取出元素，这会导致 breads 一直没有剩余空间。所以只能是生产者自己释放锁，让其他协作线程 (消费者线程) 有机会运行。</p><ol start="9"><li>什么是 NIO？为什么 NIO 能轻松支持上万个连接同时在线？</li></ol><p>NIO 的全名是同步非阻塞 IO 模型。NIO 能轻松支持上万个连接同时在线，这得益于它的事件选择机制。NIO 只需要少量 IO 线程（每一个 IO 线程内部会创建一个事件选择器）就可以服务上万个连接。因为每进行一次事件就绪选择，IO 线程需要处理的只有那些就绪的连接，在IO 层面没有就绪的连接是不需要进行处理的。这就节省了大量的线程资源，不会像 BIO 那样，一个连接不管当下是否有数据读写，都必须占用一个线程。</p><ol start="10"><li>我们在使用 NIO 构建的服务端时，如果服务端处理压力较大，可以在应用层采用快速失败拒绝连接。但是除此之外，在网络层，你还有什么办法限制服务端的流量呢？</li></ol><p>在网络层，我们可以暂时停止注册读事件，这样这个连接就不会从网卡中读取数据了，数据会停留在底层 Socket 的读缓冲区。由于 TCP 内部拥有拥塞控制，如果接受端没有从网卡中读取数据，也就不会发送 ACK 确认到源端了。源端无法写入更多数据，这就在网络层实现了拥塞控制，实现了限流。</p><ol start="11"><li>通过 NIO 通道向网络中写数据之前，需要注册写事件吗？那什么时候需要注册写事件呢？</li></ol><p>写数据之前不需要注册写事件，写事件一般是等底层 NioSocketChannel 的底层缓存区满了，无法再向网络中写入数据时，再注册通道的写事件，等待缓冲区空闲时通知应用程序继续将剩余数据写入到网络中。</p><ol start="12"><li>一个网络请求在发送端、接受端通常需要经历哪些步骤，Netty 又是采用什么线程模型使这些步骤合理高效运作的？</li></ol><p>一个网络请求发送与接收响应结果通常涉及编码、往网络中写数据（Write）、从网络中读取数据（Read）、解码、业务逻辑处理、发送响应结果和接受响应结果等步骤。过程图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/8.png" alt=""></a></p><p>Netty 的线程模型采取的是业界的主流线程模型，也就是主从多 Reactor 模型：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%AD%E9%97%B4%E4%BB%B6%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/%25E6%259C%259F%25E4%25B8%25AD%25E6%25B5%258B%25E8%25AF%2595%25E7%25AD%2594%25E6%25A1%2588-%25E8%25BF%2599%25E4%25BA%259B%25E9%2597%25AE%25E9%25A2%2598%25EF%25BC%258C%25E4%25BD%25A0%25E9%2583%25BD%25E7%25AD%2594%25E5%25AF%25B9%25E4%25BA%2586%25E5%2590%2597%25EF%25BC%259F/9.png" alt=""></a></p><p>它的设计重点主要包括 Netty Boss Group、Nettty Work Group、Business Thread Group 线程组这三个线程组。 更详细的说明你可以参考第 8 讲。</p><p>好了，我们本节课的答疑就到这里了，如果有其他问题，欢迎留言与我互动，我们下节课再见。</p>`,62)])])}const o=s(e,[["render",a]]);export{F as __pageData,o as default};
